begin;
create extension if not exists pgtap with schema extensions;
select extensions.plan(19);
select ok((select relrowsecurity from pg_class where oid='public.notification_preferences'::regclass),'notification preferences have RLS');
select ok((select relrowsecurity from pg_class where oid='public.notification_jobs'::regclass),'notification jobs have RLS');
select ok((select relrowsecurity from pg_class where oid='public.notification_deliveries'::regclass),'notification delivery logs have RLS');
select ok((select relrowsecurity from pg_class where oid='public.web_push_subscriptions'::regclass),'push subscriptions have RLS');
select ok(exists(select 1 from pg_indexes where schemaname='public' and indexname='notification_jobs_ready_idx'),'notification queue has ready-job index');
select ok(has_function_privilege('service_role','public.claim_notification_jobs(integer)','EXECUTE'),'worker can claim queue jobs');
select ok(not has_function_privilege('authenticated','public.claim_notification_jobs(integer)','EXECUTE'),'clients cannot claim queue jobs');
select ok(exists(select 1 from pg_trigger where tgrelid='public.appointments'::regclass and tgname='appointment_notification_events'),'appointment events enqueue reminders and review requests');
select ok(exists(select 1 from pg_trigger where tgrelid='public.vaccinations'::regclass and tgname='vaccine_due_notification'),'vaccine due events enqueue reminders');
select ok(exists(select 1 from pg_trigger where tgrelid='public.sos_dispatches'::regclass and tgname='sos_dispatch_notification'),'SOS dispatch events enqueue urgent notifications');
select ok((select relrowsecurity from pg_class where oid='public.feature_flags'::regclass),'feature flags have RLS');
select ok(exists(select 1 from pg_trigger where tgrelid='public.feature_flags'::regclass and tgname='admin_audit_flags'),'feature flag mutations are audited');
select ok(exists(select 1 from pg_trigger where tgrelid='public.clinic_verification_requests'::regclass and tgname='admin_audit_verification'),'clinic verification decisions are audited');
select ok(exists(select 1 from pg_trigger where tgrelid='public.reviews'::regclass and tgname='admin_audit_reviews'),'review moderation is audited');
select ok(exists(select 1 from pg_trigger where tgrelid='public.community_posts'::regclass and tgname='require_aal2_posts'),'direct post moderation requires AAL2');
select ok(exists(select 1 from pg_trigger where tgrelid='public.community_appeals'::regclass and tgname='require_aal2_appeals'),'direct appeal decisions require AAL2');
select ok(exists(select 1 from pg_trigger where tgrelid='public.profiles'::regclass and tgname='require_aal2_profiles'),'direct account suspension requires AAL2');
select ok(position('aal2' in pg_get_functiondef('public.admin_set_feature_flag(text,boolean)'::regprocedure))>0,'sensitive feature flag changes require AAL2');
select ok(exists(select 1 from pg_trigger where tgrelid='public.audit_logs'::regclass and tgname='audit_logs_append_only'),'audit history remains append-only');
select * from extensions.finish();
rollback;
